import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'github-issues-fetch',
  description: 'Fetches a bounded, incremental window of GitHub repository issues.',
  inputs: {
    cursor: { type: 'json', description: 'Last successfully synced GitHub updated_at value.' },
    config: { type: 'json', description: 'Repository owner, name, and optional API base URL.', required: true },
  },
  outputs: {
    records: { type: 'array', description: 'GitHub issues ready for connector normalization.', itemType: 'object' },
    cursor: { type: 'string', description: 'Newest updated_at value processed.', nullable: true },
    rateLimited: { type: 'boolean', description: 'True when GitHub throttled the pass; the engine backs off and retries from this cursor.', nullable: true },
    partial: { type: 'boolean', description: 'True when more pages remained after the per-pass page budget.', nullable: true },
  },
  requires: ['network', 'credential:$credential'],
} as const);

type Config = { owner?: unknown; repository?: unknown; apiBaseUrl?: unknown };
type Issue = Record<string, unknown> & { updated_at?: unknown; pull_request?: unknown };
const input = gezel.input as { cursor?: unknown; config?: Config };
const config = input.config ?? {};
const owner = typeof config.owner === 'string' ? config.owner.trim() : '';
const repository = typeof config.repository === 'string' ? config.repository.trim() : '';
if (!owner || !repository) throw new Error('GitHub owner and repository are required.');

const apiBaseUrl =
  typeof config.apiBaseUrl === 'string' && config.apiBaseUrl.trim()
    ? config.apiBaseUrl.trim().replace(/\/+$/, '')
    : 'https://api.github.com';
let apiOrigin: string;
try {
  const parsed = new URL(apiBaseUrl);
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') throw new Error('bad protocol');
  apiOrigin = parsed.origin;
} catch {
  throw new Error('GitHub API base URL must be an absolute HTTP or HTTPS URL.');
}

const params = new URLSearchParams({
  state: 'all',
  sort: 'updated',
  direction: typeof input.cursor === 'string' ? 'asc' : 'desc',
  per_page: '100',
});
if (typeof input.cursor === 'string' && input.cursor) params.set('since', input.cursor);
let nextUrl =
  apiBaseUrl + '/repos/' + encodeURIComponent(owner) + '/' + encodeURIComponent(repository) + '/issues?' + params;
let nextCursor = typeof input.cursor === 'string' ? input.cursor : null;
const records: Issue[] = [];
let rateLimited = false;

function nextPage(link: string | undefined): string | null {
  if (!link) return null;
  for (const part of link.split(',')) {
    const match = part.match(/<([^>]+)>;\s*rel="next"/);
    if (match?.[1]) return match[1];
  }
  return null;
}

function isThrottle(status: number, headers: Record<string, string | undefined>): boolean {
  if (status === 429) return true;
  return status === 403 && (headers['x-ratelimit-remaining'] === '0' || Boolean(headers['retry-after']));
}

for (let page = 0; page < 5 && nextUrl; page++) {
  const target = new URL(nextUrl);
  if (target.origin !== apiOrigin) throw new Error('GitHub pagination changed origin; refusing to forward the token.');
  const headers = {
    Accept: 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28',
    'User-Agent': 'Gezel-GitHub-Issues-Connector',
  };
  let response;
  try {
    response = await gezel.http.authed(target.toString(), {
      credential: '$credential',
      headers,
    });
  } catch (error) {
    if ((error as { code?: string }).code !== 'CREDENTIAL_MISSING') throw error;
    response = await gezel.http.request(target.toString(), { headers });
  }
  if (isThrottle(response.status, response.headers)) {
    // Emit what this pass already collected with the cursor those records
    // reached, and flag the throttle instead of throwing: a throw voids the
    // batch and re-fetches the same window next tick, which is exactly how
    // rate-limited APIs get hammered. The engine persists the cursor only
    // after a clean write and applies its jittered backoff to the binding.
    rateLimited = true;
    break;
  }
  if (!response.ok) {
    throw new Error('GitHub issues request failed (' + response.status + '): ' + response.body.slice(0, 240));
  }
  const pageItems = JSON.parse(response.body) as unknown;
  if (!Array.isArray(pageItems)) throw new Error('GitHub returned a non-array issues response.');
  for (const raw of pageItems) {
    if (!raw || typeof raw !== 'object') continue;
    const issue = raw as Issue;
    const updatedAt = typeof issue.updated_at === 'string' ? issue.updated_at : '';
    if (updatedAt && (!nextCursor || updatedAt > nextCursor)) nextCursor = updatedAt;
    if (issue.pull_request) continue;
    const labels = Array.isArray(issue.labels)
      ? issue.labels
          .map((label) =>
            typeof label === 'string'
              ? label
              : label && typeof label === 'object'
                ? String((label as Record<string, unknown>).name ?? '')
                : '',
          )
          .filter(Boolean)
      : [];
    const assignees = Array.isArray(issue.assignees)
      ? issue.assignees
          .map((person) =>
            person && typeof person === 'object'
              ? String((person as Record<string, unknown>).login ?? '')
              : '',
          )
          .filter(Boolean)
      : [];
    records.push({
      ...issue,
      gezel_repository: owner + '/' + repository,
      gezel_labels: labels,
      gezel_assignees: assignees,
    });
  }
  const candidate = nextPage(response.headers.link);
  nextUrl = candidate && new URL(candidate).origin === apiOrigin ? candidate : '';
}

const cursorOut = records.length > 0 ? nextCursor : typeof input.cursor === 'string' ? input.cursor : null;
gezel.output({
  records,
  cursor: rateLimited ? cursorOut : nextCursor,
  ...(rateLimited ? { rateLimited: true } : {}),
  ...(nextUrl && !rateLimited ? { partial: true } : {}),
});
